import re
import imaplib
import email
from email.header import decode_header

def check_gmail_notifications(gmail_credentials: dict, last_check_time: str = None) -> dict:
    try:
        # Connect to Gmail IMAP
        imap = imaplib.IMAP4_SSL('imap.gmail.com')
        imap.login(gmail_credentials['username'], gmail_credentials['password'])
        imap.select('INBOX')

        # Search for WILLOW sync emails
        search_criteria = 'FROM "sandbox-willow@genspark.ai" SUBJECT "🔄 WILLOW Sync"'
        if last_check_time:
            search_criteria += f' SINCE "{format_imap_date(last_check_time)}"'

        status, messages = imap.search(None, search_criteria)

        if status != 'OK':
            return {'success': False, 'error': 'IMAP search failed'}

        message_ids = messages[0].split()
        notifications = []

        for msg_id in message_ids[-10:]:  # Process last 10 messages
            status, msg_data = imap.fetch(msg_id, '(RFC822)')

            if status == 'OK':
                raw_email = msg_data[0][1]
                msg = email.message_from_bytes(raw_email)

                # Extract sync information
                notification = parse_sync_notification(msg)
                if notification['success']:
                    notifications.append(notification)

        imap.close()
        imap.logout()

        return {
            'success': True,
            'notifications': notifications,
            'count': len(notifications)
        }

    except Exception as e:
        return {'success': False, 'error': str(e)}

def parse_sync_notification(email_msg) -> dict:
    try:
        # Extract subject
        subject = decode_header(email_msg['Subject'])[0][0]
        if isinstance(subject, bytes):
            subject = subject.decode()

        # Extract body
        body = ''
        if email_msg.is_multipart():
            for part in email_msg.walk():
                if part.get_content_type() == 'text/plain':
                    body = part.get_payload(decode=True).decode()
                    break
        else:
            body = email_msg.get_payload(decode=True).decode()

        # Parse sync ID using regex
        sync_id_match = re.search(r'WILLOW_SYNC_([a-f0-9-]{36})', body)
        if not sync_id_match:
            return {'success': False, 'error': 'Sync ID not found'}

        sync_id = sync_id_match.group(1)

        # Extract property address from subject
        property_match = re.search(r'🔄 WILLOW Sync Request: (.+)', subject)
        property_address = property_match.group(1) if property_match else 'Unknown'

